//	function printElementGroup(rmodels, group, nurX) {
function mappings2json(rmodels, group, nurX) {
	m2jretval = []
	if (group != null) {
		for (ig = 0; ig < group.length; ig++) {
			m2jretval = m2jretval.concat(logicalElement(rmodels, group[ig], nurX))
		}
	}
	//message('mappings2json= '+retval)
	return m2jretval
}

function printMatrix(fw, nurX) {
	logicalModel = model.getDesign().getLogicalDesign();
	entitySet = logicalModel.getEntitySet()
	relationSet = logicalModel.getRelationSet()
	inheritanceSet = logicalModel.getInheritanceRelationSet()
	rmodels = model.getDesign().getRelationalDesigns().toArray();
	getAllMappings(rmodels)

	allmapping = {
		"header": ['entity', 'attr']
	}
	allmapping["header"] = allmapping["header"].concat(headers(rmodels, nurX))

		//throw new Error("\nheaders: " + allmapping["header"] + "\n");
	allmapping["attrlist"] = mappings2json(rmodels, entitySet.toArray(), nurX)
	allmapping["attrlist"] = allmapping["attrlist"].concat(mappings2json(rmodels, relationSet.toArray(), nurX))

	//printElementGroup(rmodels, entitySet.toArray(), nurX)
	//printElementGroup(rmodels, relationSet.toArray(), nurX)
	allmapping["footer"] = 'created by ODM, ' + curDateStr()
	fw.write(JSON.stringify(allmapping, null, 2)); // spacing level = 2)
}

function printCVS(fw) {
	fw.write(relModel + ';;;' + EXCELLINEEND)
	fw.write('entityName;attrName;tableName;columnName' + EXCELLINEEND)
	tables = relModel.getTableSet().toArray();
	for (itpc = 0; itpc < tables.length; itpc++) {
		printCols(fw, tables[itpc])
	}
}

function print1Mapping() {
	logicalModel = model.getDesign().getLogicalDesign();
	entitySet = logicalModel.getEntitySet()
	relationSet = logicalModel.getRelationSet()
	inheritanceSet = logicalModel.getInheritanceRelationSet()
	relModel = chooseModel(relModel);
	if (relModel == null) return;
	// lies alle Mappings des gewählten Modells
	getAllMappings([relModel])

	fileName = chooseFile(exportDirec, relModel + '.csv')
	if (fileName == null) return
	fw = createFile(fileName)
	printCVS(fw)
	fw.close();
	message("Mapping file " + fileName + " for model " + relModel + " created.");
}

function printAllMapping(nurX) {
	fileName = chooseFile(exportDirec, 'AllMapping' + (nurX ? 'X' : '') + '.js')
	if (fileName == null) return
	fw = createFile(fileName)
	printMatrix(fw, nurX)
	fw.close();
	message("Mapping file " + fileName + " created.");
}

function printXMapping() {
	printAllMapping(true)
}

function printNameMapping() {
	printAllMapping(false)
}

			//scripts to handle translation of model
	var gLogNote = "LOG";
	var gCurrentLang = "DE";
	var gLanguages = "DE,EN";
	var gTranslInforegexp =/TRANSLATION\{[^}]*\}/;
	var logInitialized = false;
	var NOTESSTARTTAG = '[<tag>[\n';
	var NOTESENDTAG = '\n]<tag>]';
	var PLAINMESSAGE = 1;
	var ERRORMESSAGE = 0;
	var WARNINGMESSAGE = 2;
	var QUESTIONMESSAGE = 3;
	var gLangArray = []; 
	var gCurVersion = '';
	var CODEVERSION = '1.1';


	function fullmessage(msg,type) {
		Java.type("javax.swing.JOptionPane").showMessageDialog(null
		, msg,'ODM-Translation', type);
	}

	function error(msg) {
		fullmessage(msg,ERRORMESSAGE);
		}
	function message(msg) {
		fullmessage(msg,PLAINMESSAGE);
		}

	function initLog(){
		if (! logInitialized){
			var lNote = model.getNoteSet().getByName(gLogNote);
	     	if (lNote == null) {
	    	    		lNote = model.createNote()
		    		lNote.setName(gLogNote);
	     	}
	     	lNote.setComment("");
	     	logInitialized = true;
		}
	}
	function log(plog){
		initLog();
		var lNote = model.getNoteSet().getByName(gLogNote);
	     lNote.setComment(lNote.getComment()+"\n"+plog);
	}

	function getTranslInfo(){
		var lDesignComment = model.design.getComment();
	     lmatchTransl= lDesignComment.match(gTranslInforegexp);
	     return lmatchTransl;    
	}

	function setTranslInfo(curLang,langs,version) {
		model.design.setComment(
			"TRANSLATION{\ncurrentLang="+curLang
			+"\nlanguages="+langs
			+"\nlastSync="
			+"\nversion="+version+"\n}\n"
			+ model.design.getComment());
	}
	function updTranslInfo(curLang,langs,version,datetime) {
		curComment = model.design.getComment();
		model.design.setComment(
			curComment.replace(gTranslInforegexp,
			"TRANSLATION{\ncurrentLang="+curLang
			+"\nlanguages="+langs
			+"\nlastSync="+datetime
			+"\nversion="+version+"\n}"
			));
	}

	function buildRegExpTag(innertag,tag){
		return tag.replace('<tag>',innertag).replace(/\[/g,'\\[').replace(/\]/g,'\\]')
	}

	function textFromNote(tag,obj) {
    	note = obj.getNotes()
    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	re = new RegExp(restart + '([^]*)' + reend)
    	ma = note.match(re)
    	retval = ''
	   	if (ma != null) {
			//message("|"+reend+"|\n"+"|"+ma[0]+"|")
	   		retval = ma[1]
		}
		return retval
	}

	function textToNote(tag,obj,value) {
    	note = obj.getNotes()
    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
    	re = new RegExp(restart + '([^]*)' + reend)
    	ma = note.match(re)
		newentry = NOTESSTARTTAG.replace('<tag>',tag) 
			+ value 
			+ NOTESENDTAG.replace('<tag>',tag)
			+'\n'
	   	if (ma == null) {
	   		note = note + newentry
		} else {
			//message("|"+newentry+"|\n"+"|"+ma[0]+"|")
			note = note.replace(ma[0] , newentry)
		}

		obj.setNotes(note)
	}

	function init(istUpgrade){
		lmatchTransl = getTranslInfo();
		if (lmatchTransl == null) {
			throw new Error("\n***TRANSLATION not installed***\n");
		}
		ltext= String(lmatchTransl).match(/currentLang=[A-Z]{2}/);
		lparts = String(ltext).split("=");
		//log("curLang="+lparts[1]);
	     gCurrentLang = lparts[1];

		ltext= String(lmatchTransl).match(/languages=[A-Z,]*/);
		lparts = String(ltext).split("=");
	     //log("languages="+lparts[1]);
	     gLanguages = lparts[1]
		gLangArray = gLanguages.split(',');

		ltext= String(lmatchTransl).match(/version=[0-9\.]*/);
		lparts = String(ltext).split("=");
		gCurVersion = lparts[1]
		if (gCurVersion != CODEVERSION && !istUpgrade) {
			msg = "\n***TRANSLATION version mismatch: "
				+"expected " + CODEVERSION + " found "+gCurVersion
				+"\nPlease upgrade.***\n"
			throw new Error(msg);
		}
	}

	function doLangValue(propName,obj,value,isNote,notNull){
		lpropName = gCurrentLang + propName;
	     oldval = (isNote) ? textFromNote(lpropName,obj) : obj.getProperty(lpropName);
		for (il=0;il<gLangArray.length;il++) {
			// nur die fremden Sprachen ersetzen
			flang = gLangArray[il]
			if (flang != gCurrentLang) {
				// if value contains *xx*, don't add another one
				if (value.match(/^\*[A-Z]{2}\* /)) {
						lprefix =  ''
					} else {
						lprefix =  '*'+gCurrentLang+'* '			
					}
				//markiere oder fülle die fremde Properties
				fpropName = flang + propName;
				fprop = (isNote) ? textFromNote(fpropName,obj) : obj.getProperty(fpropName);
				// Falls die Fremdsprache noch automtaisch übersetzt ist ( *XX* vorneweg hat), überschreibe sie
				if (fprop.match(/^\*[A-Z]{2}\* /)) {
				   if (isNote) textToNote(fpropName,obj,lprefix+value);
					  else obj.setProperty(fpropName,lprefix+value);
				} else if (fprop.startsWith('*')) {
					// ** und * sind in Bearbeitung nichts ersetzen
				} else if (fprop == "" && value == "" && ! notNull) {
					// das Ziel ist leer, der neue Wert auch und es ist kein Mussfeld. lass das Ziel leer
				} else if (fprop == "") {
					// das Ziel ist leer aber aus einem Grund muss ich es überschreiben (siehe vorheriges IF)
				   if (isNote) textToNote(fpropName,obj,lprefix+value);
					  else obj.setProperty(fpropName,lprefix+value);
			    } else {
					// das Ziel ist gefüllt, nicht in Bearbeitung und nicht automatisch übersetzt.
					// d.h. es hat einen gültigen Wert. Markiere es, falls die Quelle wirklich geändert hat
					//**if (oldval == 'Entität 1') message("vor IF "+oldval)
					if ( ! (value == oldval 
						  || oldval.match(/^\*[A-Z]{2}\* /)
						  || oldval.startsWith("**")
						  || oldval.startsWith("*")) ) {
						  //**if (oldval == 'Entität 1') message("in IF "+oldval)
						  // die Quelle ist kein Feld, das in Bearbeitung oder autmoatisch übersetzt ist
						  if (isNote) textToNote(fpropName,obj,"*"+fprop);
					   		else obj.setProperty(fpropName,"*"+fprop)
					}
				}
			}
		}
		// die Werte der CurrentLang kommen aus dem Objekt, überschreibe immer
		if (isNote) textToNote(lpropName,obj,value);
		   else obj.setProperty(lpropName, value);
	}

	function doProperty(propName,obj,value,notNull){
		doLangValue(propName,obj,value,false,notNull);
	}

	function doNote(tag,obj,value) {
		doLangValue(tag,obj,value,true,false);
	}

	function fuellUDP(){
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { //
			ent = entities[ie];
			doProperty("_ENTI_NAME",ent,ent.getName(),true)
			doNote("_ENTI_COMMENT",ent,ent.getComment())
			doProperty("_ENTI_SYNONYM",ent,ent.getSynonym())

			attrs = ent.getAttributes().toArray();
			//log("Attrs="+attrs.length)
			for (ia=0;ia<attrs.length;ia++) { //
				attr = attrs[ia];
				for (il=0;il<gLangArray.length;il++) {
					doProperty("_ATTR_NAME",attr,attr.getName(),true);
					doNote("_ATTR_COMMENT",attr,attr.getComment());			
				}
			}
		ent.setDirty(true);
		}
		relationships = model.getRelationSet().toArray();
		for (ir=0;ir<relationships.length;ir++) { //
			rel = relationships[ir];
			sourcename = rel.getNameOnSource()
			targetname = rel.getNameOnTarget()
			//if (i > 0) throw new Error ("\n"+gLangArray[i]+"_RELA_TEXT_FROM"+"\n"+gLangArray.length);
			doProperty("_RELA_TEXT_FROM",rel,sourcename)
			doProperty("_RELA_TEXT_TO",rel,targetname)	
			rel.setDirty(true);
		}
	}

	function setProperties(lang){
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { //
			ent = entities[ie];
			ent.setName(ent.getProperty(lang+"_ENTI_NAME"));
			ent.setComment(textFromNote(lang+"_ENTI_COMMENT",ent))
			ent.setSynonym(ent.getProperty(lang+"_ENTI_SYNONYM"));

			attrs = ent.getAttributes().toArray();
			//log("Attrs="+attrs.length)
			for (ia=0;ia<attrs.length;ia++) { //
				attr = attrs[ia];
				//log(attr.getName(),attr.getComment());
				attr.setName(attr.getProperty(lang+"_ATTR_NAME"));
				attr.setComment(textFromNote(lang+"_ATTR_COMMENT",attr))
			}		
			ent.setDirty(true);
		}
		relationships = model.getRelationSet().toArray();
		for (ir=0;ir<relationships.length;ir++) { 
			rel = relationships[ir];
			rel.setNameOnSource(rel.getProperty(lang+"_RELA_TEXT_FROM"));
			rel.setNameOnTarget(rel.getProperty(lang+"_RELA_TEXT_TO"));
			rel.setDirty(true);
		}
	}

	function curDateStr(){
		var currentdate = new Date();
		return  currentdate.getDate() 
		+ "/" + (currentdate.getMonth()+1) 
		+ "/" + currentdate.getFullYear() + "  " 
		+ currentdate.getHours() + ":" 
		+ currentdate.getMinutes() + ":" + currentdate.getSeconds();
	}

	function changeLang(pfromLang,ptoLang){
		//log("3:"+gLanguages);
	//	log("change from " + pfromLang + " to " + ptoLang);
		fuellUDP();
		setProperties(ptoLang);
		gCurrentLang = ptoLang;
		updTranslInfo(gCurrentLang, gLanguages
					,gCurVersion,curDateStr());	
		model.design.setDirty(true);
	}

	function initTranslation() {
		lmatchTransl= getTranslInfo()
		if (lmatchTransl == null) {
			setTranslInfo(gCurrentLang
			,gLanguages,CODEVERSION);		
		} else {
			lversion = String(lmatchTransl).match(/version=[0-9\.]*/);
			throw new Error("\n***TRANSLATION ("+lversion+") already installed***\n");
		}
		//hier gibt es einen Eintrag für die Translation
		init();

		fuellUDP();

		updTranslInfo(gCurrentLang, gLanguages
					 ,gCurVersion,curDateStr());
		model.design.setDirty(true);
		message ("TRANLSATION installed current-language="+gCurrentLang
		         + " languages="+gLanguages+" version="+gCurVersion
			        ,PLAINMESSAGE);
	}

	function changeLanguage() {
		init();
		options = [];
		lcurlang = gCurrentLang
		for (il=0;il<gLangArray.length;il++) {
			if (gLangArray[il] != lcurlang) {
				options.push(gCurrentLang + '->' + gLangArray[il])
			}
		}
		if (options.length == 1) {
			antwort = options[0]
		} else {
			antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null, 
	        	"Choose language change",
				"Change language",
				QUESTIONMESSAGE,
				null, 
				options, 
				options[0]);
		}
        if (antwort != null){
			toLang = antwort.substr(-2)
			//Java.type("javax.swing.JOptionPane").showMessageDialog(null, antwort+'|'+toLang);
			changeLang(gCurrentLang,toLang);
			message ("Model language changed from "+lcurlang+" to "+toLang
						+".\n Please hide and re-display labels."
			        ,PLAINMESSAGE);
		}
	}

	function upgrade09_to_10() {
		// move comments from properties to comments
		entities = model.getEntitySet().toArray();
		for (ie=0;ie<entities.length;ie++) { 
			ent = entities[ie];
			for (il=0;il<gLangArray.length;il++) {
				// nur die fremden Sprachen ersetzen
				lang = gLangArray[il];
				textToNote(lang+"_ENTI_COMMENT",ent,ent.getProperty(lang+"_ENTI_COMMENT"));

				attrs = ent.getAttributes().toArray();
				for (ia=0;ia<attrs.length;ia++) { //
					attr = attrs[ia];
					textToNote(lang+"_ATTR_COMMENT",attr,attr.getProperty(lang+"_ATTR_COMMENT"));
				}
			}
			ent.setDirty(true);
		}
	}
	function upgrade10_to_11() {
		// nothing to update so far
	}

	function upgradeTranslation () {
		init(true);				
		//1.0 has no upgrades
		if (gCurVersion  == CODEVERSION) {
			message("TRANSLATE: latest version ("+gCurVersion+") is installed")
		} else {
			upgraded = false
			if (gCurVersion == "0.9") {
				upgrade09_to_10();
				gCurVersion = "1.0";
				upgraded = true
			}
			if (gCurVersion == "1.0") {
				upgrade10_to_11();
				gCurVersion = "1.1";
				upgraded = true
			}
			if (upgraded) {
				updTranslInfo(gCurrentLang, gLanguages
					 ,CODEVERSION,curDateStr());	
				message("TRANSLATE: latest version ("+CODEVERSION+") is now installed")
			} else {
			error("\nTRANSLATE: unknown version ("+gCurVersion+").\n"
					+"Please contact support\n");
			}
		}			
	}

