			var CODEVERSION = '2.0'
var PLAINMESSAGE = 1;
var ERRORMESSAGE = 0;
var WARNINGMESSAGE = 2;
var QUESTIONMESSAGE = 3;
var tabanz = 0
var colanz = 0
var colmapanz = 0
var tabmapanz = 0
var lasttabmapping = ""
