function chooseModel(rmodel) {
	var rmodels = model.getDesign().getRelationalDesigns().toArray();
	if (rmodels.length == 0) throw new Error("\n***MAPPING: no relational models available ***\n");
	if (rmodels.length == 1) {
		antwort = rmodels[0]
	} else {
		if (rmodel == null) rmodel = rmodels[0]
		antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null,
			"Choose relational model",
			"choose model",
			QUESTIONMESSAGE,
			null,
			rmodels, rmodel);
	}
	return antwort
